11|      <section className="home-hero" aria-label="Featured book">
12|        <img
13|          className="home-hero-img"
14|          src={favorite.cover}
15|          alt={favorite.coverAlt}
16|          width={700}
17|          height={700}
18|        />
19|        <div>
20|          <span className="home-eyebrow">★ Our favorite</span>
21|          <h1 className="home-title">{favorite.title}</h1>
22|          <p className="home-byline">
23|            {favorite.author} · {favorite.year} · {readingMinutes(favorite.words)}
24|          </p>
25|          <p className="home-lede">
26|            Every scene has its own music, picked to match what is happening on the page. Ready to
27|            read right now, music and all. No waiting.
28|          </p>
29|          <Link className="home-button" href={`/read/${favorite.id}`}>
30|            Start reading
31|          </Link>
32|        </div>
33|      </section>
34|      {others.length > 0 && (
35|        <section className="home-section" aria-label="More from the library">
36|          <h2 className="home-section-title">More from the library</h2>
37|          <ul className="home-grid">
38|            {others.map((book) => (
39|              <li key={book.id}>
40|                <Link className="home-text-button" href={`/read/${book.id}`}>
41|                  {book.title}
42|                </Link>
43|                <p className="home-muted">
44|                  {book.author} · {readingMinutes(book.words)}
45|                </p>
46|              </li>
47|            ))}
48|          </ul>
49|        </section>
50|      )}
51|    </>
52|  );
53|}

