1|/* HomeKit: tiny shared runtime for the home-v2 prototypes.
2|   Depends on icons.js (GEO, SKINS, SKIN_NAMES, icon(), MUSIC, ornament(), coverArt()). */
3|(function(){
4|  const LS='lectoria.skin';
5|  const DESC={engraving:'Ink-engraved plates on cream, like 1900',watercolor:'Soft blue washes and a loose brush',ink:'Blue ballpoint doodles in the margin'};
6|  const PICTURES={engraving:'Denslow, 1900',watercolor:'Storybook watercolor',ink:'Pen and ink'};
7|  const reduce=matchMedia('(prefers-reduced-motion: reduce)');
8|  const subs=[];
9|  const root=document.documentElement;
10|  function get(){return root.dataset.skin||'engraving';}
11|  function set(skin, fromEl){
12|    if(!SKINS.includes(skin)||skin===get()) return;
13|    if(fromEl&&fromEl.getBoundingClientRect){const r=fromEl.getBoundingClientRect();
14|      root.style.setProperty('--vx',((r.left+r.width/2)/innerWidth*100)+'%');root.style.setProperty('--vy',((r.top+r.height/2)/innerHeight*100)+'%');}
15|    const apply=()=>{root.dataset.skin=skin;try{localStorage.setItem(LS,skin)}catch(e){};subs.forEach(f=>f(skin));};
16|    if(document.startViewTransition&&!reduce.matches) document.startViewTransition(apply); else apply();
17|  }
18|  function next(fromEl){const i=SKINS.indexOf(get());set(SKINS[(i+1)%SKINS.length],fromEl);}
19|  function onChange(f){subs.push(f);}
20|  /* Replays the skin's click animation (--press) on an element: state-change only, never idle. */
21|  function press(el){if(!el||reduce.matches)return;el.classList.remove('pressed');void el.offsetWidth;el.classList.add('pressed');setTimeout(()=>el.classList.remove('pressed'),420);}
22|  /* Small icon from the shared registry, already wrapped for sizing. */
23|  function I(name,cls=''){return `<span class="ic ${cls}">${icon(name)}</span>`;}
24|  /* A swatch of a skin: the music-style art drawn in that skin (always that skin, regardless of current). */
25|  function swatch(skin){const cur=root.dataset.skin;root.dataset.skin=skin;const s=MUSIC[skin](1);root.dataset.skin=cur;return s;}
26|  window.HomeKit={SKINS,NAMES:SKIN_NAMES,DESC,PICTURES,get,set,next,onChange,press,I,swatch,reduce};
27|})();

